// 目录只选择来源绑定，状态必须完整原件；不从裁剪后的history猜补缺行。
#include "resident/checkpoint/checkpoint_decode_lifecycle.hpp"
#include "private_shop_command_results_codec.hpp"
#include "resident/domains/local_economy/economic_payload_guard.hpp"
namespace hanmo::resident {
Outcome<PrivateShopCommandResultsCatalog> decode_private_shop_command_results_catalog(const BoundaryValue& raw){try{auto v=validate_economic_payload_fields(raw);if(!v.ok)return {false,{},v.error};PrivateShopCommandResultsCatalog c;dynamic_economy_codec::decode(raw,c,private_shop_command_results_module);if(c.version!=1)return {false,{},common_failure("UnsupportedPrivateShopCommandResultsVersion").error};return {true,std::move(c),{}};}catch(const boundary::DecodeFailure& e){return {false,{},e.error};}}
Outcome<std::optional<PrivateShopCommandResultsCatalog>> decode_private_shop_command_results_profile(const BoundaryValue& scenario,const std::vector<StableId>& caps){
 const auto* dynamic=scenario.find("dynamic_world");const auto* block=dynamic?dynamic->find(private_shop_command_results_module):nullptr;if(!block)return {true,std::nullopt,{}};auto unique=validate_economic_payload_fields(*dynamic);if(!unique.ok)return {false,{},unique.error};
 try{if(boundary::get_string(*dynamic,"profile","dynamic_world")!="local_society_v1"||std::find(caps.begin(),caps.end(),private_shop_command_results_capability)==caps.end())return {false,{},common_failure("PrivateShopCommandResultsProfileRequired").error};auto shops=decode_private_shop_profile(scenario,caps);if(!shops.ok)return {false,{},shops.error};if(!shops.value)return {false,{},common_failure("PrivateShopCommandResultsShopsRequired").error};auto result=decode_private_shop_command_results_catalog(*block);if(!result.ok)return {false,{},result.error};return {true,std::optional<PrivateShopCommandResultsCatalog>{std::move(result.value)},{}};}catch(const boundary::DecodeFailure& e){return {false,{},e.error};}
}
Outcome<PrivateShopCommandResultsState> decode_private_shop_command_results_state(const BoundaryValue& raw){try{auto v=validate_economic_payload_fields(raw);if(!v.ok)return {false,{},v.error};PrivateShopCommandResultsState s;dynamic_economy_codec::decode(raw,s,private_shop_command_results_module);if(s.version!=1)return {false,{},common_failure("UnsupportedPrivateShopCommandResultsVersion").error};return {true,std::move(s),{}};}catch(const boundary::DecodeFailure& e){return {false,{},e.error};}}
Status emit_private_shop_command_results_state_fields(ProjectionWriter& w,const PrivateShopCommandResultsState& s){if(s.version!=1)return w.reject("UnsupportedPrivateShopCommandResultsVersion",private_shop_command_results_module);return dynamic_economy_codec::emit_fields(w,s);}
BoundaryValue encode_private_shop_command_results_state(const PrivateShopCommandResultsState& s){BoundaryValue out;BoundaryProjectionWriter writer(out);auto valid=writer.object("",[&](auto& w){return emit_private_shop_command_results_state_fields(w,s);});if(valid.ok)valid=writer.finish();if(!valid.ok)throw boundary::DecodeFailure{valid.error};return out;}
Status visit_private_shop_command_results_checkpoint(CodecVisitor& v,PrivateShopCommandResultsState& s){if(!v.reading()&&s.version!=1)return v.reject("UnsupportedPrivateShopCommandResultsVersion",private_shop_command_results_module);auto valid=dynamic_economy_codec::checkpoint(v,private_shop_command_results_module,s);if(!valid.ok)return valid;return s.version==1?v.status():v.reject("UnsupportedPrivateShopCommandResultsVersion",private_shop_command_results_module);}
Status validate_private_shop_command_results_pair(bool enabled,bool shops,const std::vector<std::pair<StableId,StableId>>& modules){Integer selected=0,original=0;for(const auto& m:modules){if(m.first==private_shop_command_results_module){if(m.second!="1"||++selected!=1)return common_failure("PrivateShopCommandResultsProfileMismatch");}if(m.first==private_shop_module){if(m.second!="1"||++original!=1)return common_failure("PrivateShopCommandResultsPairRequired");}}if(selected!=(enabled?1:0)||original!=(shops?1:0)||enabled&&!shops)return common_failure("PrivateShopCommandResultsPairRequired");return common_success();}
}
